// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {MathLib, IOracle} from "./Lib.sol";

abstract contract Owned {
    address public owner;
    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }
    constructor() { owner = msg.sender; }
}

abstract contract BaseVault is Owned {
    using MathLib for uint256;

    struct Position { uint128 shares; uint64 since; }

    uint256 public totalAssets;
    mapping(address => Position) internal positions;
    IOracle public oracle;
    uint256[] public history;

    event Deposited(address indexed user, uint256 amount);

    function fee(uint256 amount) internal view virtual returns (uint256) {
        return amount / 100;
    }

    function deposit(uint256 amount) external returns (uint256 shares) {
        uint256 f = fee(amount);
        shares = (amount - f).mulDiv(1e18, _price());
        positions[msg.sender].shares += uint128(shares);
        totalAssets += amount;
        history.push(amount);
        emit Deposited(msg.sender, amount);
    }

    function deposit(uint256 amount, address to) external returns (uint256) {
        positions[to].since = uint64(block.timestamp);
        return amount;
    }

    function _price() internal view returns (uint256) {
        return oracle.price();
    }

    function setOracle(IOracle o) external onlyOwner {
        oracle = o;
    }
}

