pragma solidity ^0.8.20;

library MathLib {
    function mulDiv(uint256 a, uint256 b, uint256 d) internal pure returns (uint256) {
        return (a * b) / d;
    }
}

interface IOracle {
    function price() external view returns (uint256);
}

