// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {BaseVault} from "./Base.sol";
import {IOracle} from "./Lib.sol";

contract Vault is BaseVault {
    uint256 public feeBps = 50;

    function fee(uint256 amount) internal view override returns (uint256) {
        return super.fee(amount) + (amount * feeBps) / 10_000;
    }

    function sweep(address payable to) external onlyOwner {
        (bool ok, ) = to.call{value: address(this).balance}("");
        require(ok);
        delete totalAssets;
    }

    function preview(uint256 amount) external view returns (uint256) {
        return this.quote(amount);
    }

    function quote(uint256 amount) public view returns (uint256) {
        return fee(amount);
    }
}

contract Oracle is IOracle {
    function price() external pure returns (uint256) { return 1e18; }
}
